   File.SetLastWriteTimeUtc(old,DateTime.UtcNow.AddDays(-8));var item=Maintenance.Scan(tdir).Single();File.AppendAllText(old,"changed");Throws(()=>j.Quarantine(item,tdir),"Quarantine rejects stale preview");File.SetLastWriteTimeUtc(old,DateTime.UtcNow.AddDays(-8));item=Maintenance.Scan(tdir).Single();j.Quarantine(item,tdir);File.WriteAllText(old,"new user file");Throws(()=>j.Restore(j.Items.Last()),"Quarantine recovery refuses to overwrite a new file");Assert(File.ReadAllText(old)=="new user file","New file preserved on quarantine conflict");
