  static void SteamTests(string root){
   string a=Path.Combine(root,"SteamLibrary A"),b=Path.Combine(root,"SteamLibrary B"),escapedA=a.Replace("\\","\\\\"),escapedB=b.Replace("\\","\\\\");string vdf="\"libraryfolders\" { \"1\" { \"path\" \""+escapedA+"\" } \"2\" \""+escapedB+"\" }";var libraries=GameDiscovery.SteamLibraryPaths(vdf);Assert(libraries.Contains(a)&&libraries.Contains(b),"Steam VDF discovers modern and legacy secondary libraries");
   string apps=Path.Combine(a,"steamapps"),gameFolder=Path.Combine(apps,"common","Steam Fixture");Directory.CreateDirectory(gameFolder);string manifest=Path.Combine(apps,"appmanifest_900001.acf");Directory.CreateDirectory(apps);File.WriteAllText(manifest,"\"AppState\" { \"appid\" \"900001\" \"name\" \"Steam Fixture\" \"installdir\" \"Steam Fixture\" \"StateFlags\" \"4\" }");var game=GameDiscovery.SteamManifest(manifest);Assert(game.AppId=="900001"&&game.InstallState=="4"&&game.Folder==gameFolder,"Steam manifest preserves App ID, state and installed path");File.WriteAllText(manifest,"\"AppState\" { \"appid\" \"900001\" \"name\" \"Steam Fixture\" \"installdir\" \"Steam Fixture\" \"StateFlags\" \"1\" }");Assert(GameDiscovery.SteamManifest(manifest)==null,"Steam uninstalled manifest excluded");Assert(GameDiscovery.Distinct(new[]{game,new FoundGame{Name="duplicate",Source="Steam",AppId="900001",Launch="steam://rungameid/900001"}}).Count==1,"Steam games deduplicate by App ID");
   game.SteamRoot=Path.Combine(root,"Steam Client");string grid=Path.Combine(game.SteamRoot,"appcache","librarycache");Directory.CreateDirectory(grid);string art=Path.Combine(grid,"900001_library_600x900.jpg");File.WriteAllText(art,"corrupt fixture");Assert(SteamArtwork.FindLocal(game,"cover")==null,"Corrupt local Steam artwork ignored");using(var bitmap=new System.Drawing.Bitmap(64,64))bitmap.Save(art,System.Drawing.Imaging.ImageFormat.Jpeg);Assert(SteamArtwork.FindLocal(game,"cover")==art,"Local Steam library cover preferred when valid");
   byte[] imageBytes;using(var bitmap=new System.Drawing.Bitmap(64,64))using(var stream=new MemoryStream()){bitmap.Save(stream,System.Drawing.Imaging.ImageFormat.Jpeg);imageBytes=stream.ToArray();}string cache=Path.Combine(root,"cache.jpg");int requests=0;SteamArtwork.ResponseFactory=(url,token)=>{requests++;return System.Threading.Tasks.Task.FromResult(new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=new System.Net.Http.ByteArrayContent(imageBytes)});};string downloaded=SteamArtwork.GetCachedDownload("https://fixture.invalid/art.jpg",cache,System.Threading.CancellationToken.None).GetAwaiter().GetResult();Assert(downloaded==cache&&File.Exists(cache),"Mocked CDN image validated and atomically cached");string reused=SteamArtwork.GetCachedDownload("https://fixture.invalid/art.jpg",cache,System.Threading.CancellationToken.None).GetAwaiter().GetResult();Assert(reused==cache&&requests==1,"Valid artwork cache prevents repeat download");SteamArtwork.ResponseFactory=(url,token)=>System.Threading.Tasks.Task.FromResult(new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.NotFound));Assert(SteamArtwork.GetCachedDownload("https://fixture.invalid/missing.jpg",Path.Combine(root,"missing.jpg"),System.Threading.CancellationToken.None).GetAwaiter().GetResult()==null,"Mocked HTTP 404 degrades to missing artwork");SteamArtwork.ResponseFactory=(url,token)=>{throw new IOException("offline fixture");};Assert(SteamArtwork.GetCachedDownload("https://fixture.invalid/offline.jpg",Path.Combine(root,"offline.jpg"),System.Threading.CancellationToken.None).GetAwaiter().GetResult()==null,"Mocked network failure degrades to missing artwork");SteamArtwork.ResponseFactory=(url,token)=>System.Threading.Tasks.Task.FromResult(new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=new System.Net.Http.ByteArrayContent(new byte[]{1,2,3})});Assert(SteamArtwork.GetCachedDownload("https://fixture.invalid/corrupt.jpg",Path.Combine(root,"corrupt.jpg"),System.Threading.CancellationToken.None).GetAwaiter().GetResult()==null,"Mocked corrupt image response rejected");int grids=0;SteamArtwork.ResponseFactory=(url,token)=>{requests++;string body;if(url.Contains("search/autocomplete"))body="{\"success\":true,\"data\":[{\"id\":456,\"name\":\"Fixture Game\",\"types\":[\"steam\"]}]}";else{grids++;body="{\"success\":true,\"data\":[{\"url\":\"https://cdn.steamgriddb.com/grid/fixture.png\"}]}";}return System.Threading.Tasks.Task.FromResult(new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=new System.Net.Http.StringContent(body,Encoding.UTF8,"application/json")});};var otherSource=new FoundGame{Name="Fixture Game",Source="Epic Games"};string resolved=SteamArtwork.SteamGridDbCoverUrl(otherSource,"mock-key",System.Threading.CancellationToken.None).GetAwaiter().GetResult();Assert(resolved=="https://cdn.steamgriddb.com/grid/fixture.png"&&grids==1,"Non-Steam title resolves exact SteamGridDB match and retrieves grid");SteamArtwork.ResponseFactory=(url,token)=>{string body=url.Contains("search/autocomplete")?"{\"data\":[{\"id\":456,\"name\":\"Fixture Game\",\"types\":[\"steam\"]},{\"id\":457,\"name\":\"Fixture Game\",\"types\":[\"steam\"]}]}":"{\"data\":[]}";if(!url.Contains("search/autocomplete"))grids++;return System.Threading.Tasks.Task.FromResult(new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=new System.Net.Http.StringContent(body,Encoding.UTF8,"application/json")});};Assert(SteamArtwork.SteamGridDbCoverUrl(otherSource,"mock-key",System.Threading.CancellationToken.None).GetAwaiter().GetResult()==null,"Ambiguous SteamGridDB name matches are not assigned");SteamArtwork.ResponseFactory=null;
