  public static int RunSteam(string report){count=0;log=new List<string>();string root=Path.Combine(Path.GetTempPath(),"FramePilot-steam-tests-"+Guid.NewGuid().ToString("N"));try{Directory.CreateDirectory(root);SteamTests(root);File.WriteAllText(report,string.Join("\r\n",log)+"\r\n"+count+" Steam checks passed.");return 0;}catch(Exception e){log.Add(e.ToString());File.WriteAllText(report,string.Join("\r\n",log));return 1;}finally{try{Directory.Delete(root,true);}catch{}}}
